#include "shor18MQT.hpp"

void qft_dg(QuantumCircuit& qc, int qIdx0, int qIdx1, int qIdx2, int qIdx3, int qIdx4, int qIdx5, int qIdx6, int qIdx7) {
    qc.addSWAP(qIdx3, qIdx4);
    qc.addSWAP(qIdx2, qIdx5);
    qc.addSWAP(qIdx1, qIdx6);
    qc.addSWAP(qIdx0, qIdx7);
    qc.addH(qIdx0);
    qc.addCP(qIdx1, qIdx0, -M_PI/2);
    qc.addH(qIdx1);
    qc.addCP(qIdx2, qIdx0, -M_PI/4);
    qc.addCP(qIdx2, qIdx1, -M_PI/2);
    qc.addH(qIdx2);
    qc.addCP(qIdx3, qIdx0, -M_PI/8);
    qc.addCP(qIdx3, qIdx1, -M_PI/4);
    qc.addCP(qIdx3, qIdx2, -M_PI/2);
    qc.addH(qIdx3);
    qc.addCP(qIdx4, qIdx0, -M_PI/16);
    qc.addCP(qIdx4, qIdx1, -M_PI/8);
    qc.addCP(qIdx4, qIdx2, -M_PI/4);
    qc.addCP(qIdx4, qIdx3, -M_PI/2);
    qc.addH(qIdx4);
    qc.addCP(qIdx5, qIdx0, -M_PI/32);
    qc.addCP(qIdx5, qIdx1, -M_PI/16);
    qc.addCP(qIdx5, qIdx2, -M_PI/8);
    qc.addCP(qIdx5, qIdx3, -M_PI/4);
    qc.addCP(qIdx5, qIdx4, -M_PI/2);
    qc.addH(qIdx5);
    qc.addCP(qIdx6, qIdx0, -M_PI/64);
    qc.addCP(qIdx6, qIdx1, -M_PI/32);
    qc.addCP(qIdx6, qIdx2, -M_PI/16);
    qc.addCP(qIdx6, qIdx3, -M_PI/8);
    qc.addCP(qIdx6, qIdx4, -M_PI/4);
    qc.addCP(qIdx6, qIdx5, -M_PI/2);
    qc.addH(qIdx6);
    qc.addCP(qIdx7, qIdx0, -M_PI/128);
    qc.addCP(qIdx7, qIdx1, -M_PI/64);
    qc.addCP(qIdx7, qIdx2, -M_PI/32);
    qc.addCP(qIdx7, qIdx3, -M_PI/16);
    qc.addCP(qIdx7, qIdx4, -M_PI/8);
    qc.addCP(qIdx7, qIdx5, -M_PI/4);
    qc.addCP(qIdx7, qIdx6, -M_PI/2);
    qc.addH(qIdx7);

    return;
}

